import json, os, sys
cut=sys.argv[1]; files=sys.argv[2:]
for f in files:
    seen={}; turns=[]
    for line in open(f, errors='replace'):
        try: r=json.loads(line)
        except Exception: continue
        if r.get('type')=='user':
            c=r.get('message',{}).get('content')
            if isinstance(c,list):
                if any(isinstance(x,dict) and x.get('type')=='tool_result' for x in c): continue
                c=' '.join(x.get('text','') for x in c if isinstance(x,dict))
            c=c or ''
            i=c.find('# Your first task'); 
            s=c[i:i+260] if i>=0 else c[:260]
            turns.append((r.get('timestamp','')[11:19], len(c), s.replace('\n',' / ')))
        m=r.get('message') if isinstance(r.get('message'),dict) else None
        if m and 'usage' in m: seen[m.get('id') or id(m)]=(r.get('timestamp',''),m['usage'])
    w=lambda pred: sum(u.get('input_tokens',0)+u.get('cache_creation_input_tokens',0) for t,u in seen.values() if pred(t))
    print('==', os.path.basename(f)[:8], f"before {cut}: {w(lambda t:t<cut)/1e3:.1f}K after: {w(lambda t:t>=cut)/1e3:.1f}K")
    for t in turns[:8]: print('  ', t[0], t[1], t[2][:260])
EOF
